    @EventHandler( payloadType=CreateOrderEvent.class )
    public void handle( CreateOrderEvent event) {
	    LOGGER.info("handling CreateOrderEvent - " + event );
	    Order entity = new Order();
            entity.setOrderId( event.getOrderId() );
            entity.setOrderNumber( event.getOrderNumber() );
            entity.setOrderDate( event.getOrderDate() );
            entity.setTotalAmount( event.getTotalAmount() );
            entity.setTaxAmount( event.getTaxAmount() );
            entity.setShippingAmount( event.getShippingAmount() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllOrder( entity );
    }

